export function generateEbpfSocketProbe(port = 9000): string {
  return `/*
 * Auto-generated by PEA (Protocol Engineering Anything)
 * Linux eBPF Kernel Socket Filter Probe
 * Tracing binary framing on Port ${port}
 */

#include <uapi/linux/ptrace.h>
#include <net/sock.h>
#include <bcc/proto.h>

BPF_PERF_OUTPUT(events);

struct packet_event_t {
    u32 pid;
    u16 port;
    u16 len;
    u8 payload[64];
};

int trace_socket_traffic(struct pt_regs *ctx, struct sock *sk, struct msghdr *msg, size_t size) {
    u16 dport = sk->__sk_common.skc_dport;
    dport = ntohs(dport);

    if (dport != ${port}) {
        return 0;
    }

    struct packet_event_t ev = {};
    ev.pid = bpf_get_current_pid_tgid() >> 32;
    ev.port = dport;
    ev.len = (u16)size;

    bpf_probe_read_kernel(&ev.payload, sizeof(ev.payload), msg->msg_iter.iov->iov_base);
    events.perf_submit(ctx, &ev, sizeof(ev));

    return 0;
}
`;
}
